import java.util.*;
​
public class Main {
    // 判断是否是阿姆斯特朗数（即水仙花数）
    public static boolean isArmstrongNumber(int num, int n) {
        int sum = 0, temp = num;
        int[] powers = new int[10];
​
        // 预计算 0-9 的 n 次方
        for (int i = 0; i < 10; i++) {
            powers[i] = (int) Math.pow(i, n);
        }
​
        while (temp > 0) {
            sum += powers[temp % 10];
            temp /= 10;
        }
​
        return sum == num;
    }
​
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt(), m = scanner.nextInt();
        scanner.close();
​
        if (n < 3 || n > 7) {
            System.out.println("-1");
            return;
        }
​
        int start = (int) Math.pow(10, n - 1);
        int end = start * 10;
        List<Integer> armstrongList = new ArrayList<>();
​
        for (int i = start; i < end; i++) {
            if (isArmstrongNumber(i, n)) {
                armstrongList.add(i);
            }
        }
​
        if (armstrongList.isEmpty()) {
            System.out.println("-1");
        } else {
           int count = armstrongList.size();
           if (count <= m) {
            System.out.println(armstrongList.get(count-1) * m);
           } else {
            System.out.println(armstrongList.get(m));
           }
        }
    }
}
