// 计算 num 是否为 n 位的阿姆斯特朗数（即水仙花数）
bool isArmstrongNumber(int num, int n) {
    int sum = 0, temp = num;
    vector<int> powers(10, 1); // 预计算 0-9 的 n 次方
​
    for (int i = 0; i < 10; i++) {
        for (int j = 0; j < n; j++) {
            powers[i] *= i;
        }
    }
​
    while (temp > 0) {
        sum += powers[temp % 10];
        temp /= 10;
    }
​
    return sum == num;
}
​
int main() {
    int n, m;
    cin >> n >> m;
​
    if (n < 3 || n > 7) {
        cout << "-1" << endl;
        return 0;
    }
​
    int start = 1;
    for (int i = 1; i < n; i++) start *= 10;
    int end = start * 10;
​
    vector<int> armstrongList;
    for (int i = start; i < end; i++) {
        if (isArmstrongNumber(i, n)) {
            armstrongList.push_back(i);
        }
    }
​
    if (armstrongList.empty()) {
        cout << "-1" << endl;
    } else {
        if (armstrongList.size() <= m) {
            cout << 1ll * m * armstrongList[armstrongList.size() - 1];
        } else {
            cout << armstrongList[m];
        }
    }
​
    return 0;
}
